# stun (or stunning dash) in slot s can reach the foe from here
def stun_reach(s, t):
    return ability_ready(s) and slot_stun(s) > 0 and distance( position(), unit_position(t) ) <= slot_range(s) + slot_radius(s)

# single-target damage cast in slot s can reach the foe from here (no dashes, shields, heals, resets)
def dmg_reach(s, t):
