# v2: v1 plus a fuel guard on the camp-choice step. Rich-group scoring (rich_spawns, group_threat,
# group_hp, closest over a filtered set) is the most expensive part of a turn, and v1 ran out of
# fuel about 11 turns a game. When fuel is low, the rich-group check is skipped and the bot falls
# back to the cheaper gem/elk goal, so the turn finishes instead of being cut off mid-way.
# Everything else (fights, retreats, tributes, openers) is unchanged from v1.

# ---- tunable constants ----
# rough damage per turn one champion deals when clearing a camp group
CLEAR_POWER = 60
