    let rich_target = closest( minus( rich_all, respawning ) )
    if exists(rich_target) and group_threat(rich_target) * group_hp(rich_target) <= health() * CLEAR_POWER * (1 + allies_within(4)) and distance( rich_target, position() ) <= distance( nearest_goal, position() ) + RICH_DETOUR:
